import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Placeholder from 'flarum/common/components/Placeholder';
import classList from 'flarum/common/utils/classList';
import UserDirectoryListItem from './UserDirectoryListItem';
/**
 * Based on Flarum's DiscussionList.
 */
export default class UserDirectoryList extends Component {
  view() {
    const state = this.attrs.state;
    const useSmallCards = app.forum.attribute('userDirectorySmallCards');
    // The initial load has to count here too, otherwise the very first render
    // shows an empty list with no indication that anything is happening.
    const isLoading = state.isInitialLoading() || state.isLoadingNext();
    let loading;
    if (isLoading) {
      loading = m(LoadingIndicator, null);
    } else if (state.hasNext()) {
      loading = m(Button, {
        className: "Button",
        onclick: state.loadNext.bind(state)
      }, app.translator.trans('fof-user-directory.forum.page.load_more_button'));
    }
    if (state.isEmpty()) {
      // Previously this used core's `DiscussionList` class, which was a
      // copy-paste leftover — nothing styles the empty state through it.
      return m("div", {
        className: "UserDirectoryList"
      }, m(Placeholder, {
        text: app.translator.trans('fof-user-directory.forum.page.empty_text')
      }));
    }
    const pageSize = state.pageSize ?? 20;
    return m("div", {
      className: classList('UserDirectoryList', {
        'UserDirectoryList--searchResults': state.isSearchResults(),
        'UserDirectoryList--small-cards': useSmallCards
      })
    }, m("ul", {
      role: "feed",
      "aria-busy": isLoading,
      className: "UserDirectoryList-users"
    }, state.getPages().map((page, pageNum) => page.items.map((user, itemNum) => m("li", {
      key: user.id(),
      "data-id": user.id(),
      role: "article",
      "aria-setsize": -1,
      "aria-posinset": pageNum * pageSize + itemNum + 1
    }, m(UserDirectoryListItem, {
      user: user,
      useSmallCards: useSmallCards
    }))))), m("div", {
      className: "UserDirectoryList-loadMore"
    }, loading));
  }
}
flarum.reg.add('fof-user-directory', 'forum/components/UserDirectoryList', UserDirectoryList);